def selected_styles(path):
    out=["app.css"]
    if path.startswith(("/lookups","/notifications","/audit","/change-password","/replacement")):
        out.append("pages/workspace-pages.css")
    if path.startswith("/users"):
        out.append("pages/management.css")
    out.append("design-system-cyan.css")
    if path.startswith(("/users","/audit")):
        out.append("pages/admin-reports-assistant.css")
    out.extend(["pages/assistant-dock.css","navigation-color-system.css"])
    if path.startswith(("/change-password","/notifications","/audit","/lookups","/replacement")) or path.startswith("/users/"):
        out.append("pages/secondary-workspaces.css")
    return list(dict.fromkeys(out))

def shell(path,title,content,active,styles):
    css="\n".join((CSS/f).read_text(encoding="utf-8") for f in styles)
    note=".preview-note{max-width:1500px;margin:16px auto;color:#6e879b;font-size:11px}.ui-scope-chip svg{width:15px;height:15px;stroke:currentColor;fill:none}"
    return f'''<!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title}</title><style>{css}\n{note}</style></head><body data-app-version="68.49.0" data-active-role="Admin" data-workspace-path="{path}" data-page="{ {'/change-password':'account','/notifications':'notifications','/audit':'audit','/lookups':'lookups','/replacement':'replacement'}.get(path,'user-edit' if path.startswith('/users/') else 'error')}"><div class="ui-shell premium-shell">{sidebar(active)}<header class="ui-topbar premium-topbar"><button class="premium-mobile-menu" type="button" aria-label="فتح القائمة">☰</button><div class="premium-breadcrumb"><span>نظام إدارة حركات الموظفين</span><b>/</b><strong>{title}</strong></div><div class="ui-top-actions premium-top-actions"><button class="interactive-command-trigger" type="button">{svg('search')}<span>تنقل سريع</span><kbd>Ctrl K</kbd></button><button class="interactive-notification-trigger" type="button" aria-label="مركز المتابعة">{svg('bell')}</button><div class="ui-scope-chip">{svg('pin')}<span>محافظة العمل:</span><b>القاهرة</b></div></div></header><main id="main" class="ui-main premium-main with-shell">{content}<p class="preview-note">معاينة محلية باستخدام CSS المشروع ومحتوى تجريبي — لا يوجد اتصال بقاعدة البيانات.</p></main></div></body></html>'''

checks=[]
with sync_playwright() as p:
    browser=p.chromium.launch(headless=True, executable_path="/usr/bin/chromium", args=["--no-sandbox","--disable-dev-shm-usage"])
    for key,(path,title,active,content) in CONTENTS.items():
        styles=selected_styles(path)
        html=shell(path,title,content,active,styles)
        page=browser.new_page(viewport={"width":1440,"height":1000},device_scale_factor=1)
        errors=[]
        page.on("pageerror",lambda exc, arr=errors: arr.append(str(exc)))
        page.on("console",lambda msg, arr=errors: arr.append(msg.text) if msg.type=="error" else None)
        page.set_content(html,wait_until="domcontentloaded")
        for mode,width,height in [("desktop",1440,1000),("mobile",390,844),("narrow",360,800)]:
            page.set_viewport_size({"width":width,"height":height})
            page.wait_for_timeout(50)
            shot=OUT/f"{key}-{mode}.png"
            page.screenshot(path=str(shot),full_page=True,animations="disabled")
            metrics=page.evaluate("""() => ({body:document.body.scrollWidth,doc:document.documentElement.scrollWidth,height:document.documentElement.scrollHeight,viewport:innerHeight})""")
            checks.append({"page":key,"mode":mode,"file":shot.name,"viewport":width,"body_scroll_width":metrics["body"],"document_scroll_width":metrics["doc"],"horizontal_overflow":metrics["body"]>width+1 or metrics["doc"]>width+1,"page_errors":len(errors),"styles":styles})
        if key=="notifications":
            page.set_viewport_size({"width":390,"height":844})
            page.locator("#appSidebar").evaluate("el => el.classList.add('is-open')")
            shot=OUT/"notifications-mobile-sidebar-open.png"
            page.screenshot(path=str(shot),full_page=True,animations="disabled")
        page.close()
    browser.close()
summary={"release":"68.49.0","fixture_type":"synthetic content with actual project CSS","pages_rendered":len(CONTENTS),"screenshots":len(checks)+1,"errors":sum(x["page_errors"] for x in checks),"horizontal_overflow_cases":sum(x["horizontal_overflow"] for x in checks),"checks":checks}
(OUT/"preview-summary.json").write_text(json.dumps(summary,ensure_ascii=False,indent=2),encoding="utf-8")
print(json.dumps({k:v for k,v in summary.items() if k!="checks"},ensure_ascii=False,indent=2))
if summary["errors"] or summary["horizontal_overflow_cases"]:
    raise SystemExit(1)
